const ompStream = (model, text) => [
  JSON.stringify({ type: "session", sessionId: "secret-session" }),
  JSON.stringify({ type: "message", message: { role: "assistant", model, responseId: "r1", content: [{ type: "text", text }] } }),
  JSON.stringify({ type: "message_end", message: { role: "assistant", model, responseId: "r1", content: [{ type: "text", text }] } }),
  JSON.stringify({ type: "turn_end", model, responseId: "r1", message: { role: "assistant", model, responseId: "r1", content: [{ type: "text", text }] } }),
  JSON.stringify({ type: "agent_end", model, responseId: "r1", message: { role: "assistant", model, responseId: "r1", content: [{ type: "text", text }] } })
].join("\n");

