test("OMP runtime closure adds only a validated bun directory after a closed probe",async()=>{const probes=[];const calls=[];const closure=await resolveOmpRuntimeClosure({ompExecutable:"/custom/omp/bin/omp",invokingPath:"/unrelated/bin:/runtime/bin",systemDirs:["/usr/bin","/bin"],exec:async(command,args,options)=>{calls.push({command,args,options});return{stdout:"/runtime/bin/bun\n"}},checkExecutable:async path=>assert.equal(path,"/runtime/bin/bun"),probe:async path=>{probes.push(path);if(probes.length===1)throw Error("bun absent");return "omp/17.2.7"}});assert.equal(closure.runtimeExecutable,"/runtime/bin/bun");assert.deepEqual(probes,["/custom/omp/bin:/usr/bin:/bin","/custom/omp/bin:/runtime/bin:/usr/bin:/bin"]);assert.equal(probes[1].includes("/unrelated/bin"),false);assert.deepEqual(calls,[{command:"/usr/bin/which",args:["bun"],options:{env:{PATH:"/unrelated/bin:/runtime/bin"}}}]);await assert.rejects(()=>resolveOmpRuntimeClosure({ompExecutable:"/custom/omp/bin/omp",systemDirs:["/usr/bin"],probe:async()=>{throw Error("failed")},exec:async()=>({stdout:"bun\n"})}),/absolute path/);await assert.rejects(()=>resolveOmpRuntimeClosure({ompExecutable:"/custom/omp/bin/omp",systemDirs:["/usr/bin"],probe:async()=>{throw Error("failed")},exec:async()=>({stdout:"/runtime/bin/bun\n"}),checkExecutable:async()=>{throw Error("no")}}),/not executable/)});
test("OMP JSONL parser uses authoritative message_end response only", () => {
  const terminal = (model, text, responseId = "r1") => JSON.stringify({ type: "message_end", message: { role: "assistant", ...(model ? { model } : {}), responseId, content: text === null ? [] : [{ type: "text", text }] } });
  const earlier = (model, text) => JSON.stringify({ type: "message", message: { role: "assistant", model, responseId: "r1", content: [{ type: "text", text }] } });
  const end = JSON.stringify({ type: "agent_end" });
  assert.equal(parseOmpJsonl([earlier("claude-opus-5", "draft"), terminal("claude-opus-5", "final"), end].join("\n"), "claude-opus-5").text, "final");
  assert.equal(parseOmpJsonl([terminal("claude-opus-5", "final"), JSON.stringify({ type: "agent_end", message: { role: "assistant", content: [] } })].join("\n"), "claude-opus-5").text, "final");
  for (const bad of [
    "{bad}",
    [earlier("claude-opus-5", "draft"), terminal("claude-opus-5", null), end].join("\n"),
    [terminal("claude-opus-5", "one", "r1"), terminal("claude-opus-5", "two", "r2"), end].join("\n"),
    [terminal("other", "final"), end].join("\n"),
    [terminal(null, "final"), end].join("\n")
  ]) assert.throws(() => parseOmpJsonl(bad, "claude-opus-5"));
});
