  assert.deepEqual(CASES.find(c => c.id === "publish-without-fresh-confirmation").owners, ["skills/loom/PUBLISH.md", "skills/loom/AUTHORITY.md"]);
  assert.deepEqual(CASES.find(c => c.id === "independent-decision-continues-while-fact-lookup-waits").owners, ["skills/loom-grill/SKILL.md"]);
