test("judge transport exhaustion is BLOCKED identically after resume", async () => { const root=await mkdtemp(join(tmpdir(),"loom-eval-blocked-"));try{for(const arm of ["baseline","candidate"])for(const owner of new Set(CASES.flatMap(c=>c.owners))){await mkdir(join(root,arm,owner,".."),{recursive:true});await writeFile(join(root,arm,owner),arm)}const identity={dir:join(root,"baseline"),ref:"v1",commit:"0123456789abcdef0123456789abcdef01234567",dirty:false,advisory:false},candidate={...identity,dir:join(root,"candidate"),ref:"HEAD"};let calls=0;const fake=async(_command,args)=>{calls++;return{stdout:args.includes("--model=gpt-5.6-sol")?"{bad}":ompStream("claude-opus-5","Result: independent decision fact lookup not delegated\nChanged: none\nCheck: pass\nNext action: stop.")}};const first=await executeEvaluation({tier:"quick",baseline:identity,candidate,rawDir:join(root,"raw"),exec:fake,runId:"blocked",ompExecutable:"/opt/omp/bin/omp",env:isolatedChildEnv({home:"/owned/home",agentDir:"/owned/agent",ompExecutable:"/opt/omp/bin/omp"})});const count=calls,resumed=await executeEvaluation({tier:"quick",baseline:identity,candidate,rawDir:join(root,"raw"),exec:fake,runId:"blocked",ompExecutable:"/opt/omp/bin/omp",env:isolatedChildEnv({home:"/owned/home",agentDir:"/owned/agent",ompExecutable:"/opt/omp/bin/omp"})});assert.equal(calls,count);assert.deepEqual(resumed.summary,first.summary);assert.equal(first.outcome,"BLOCKED");assert.equal(first.safety,"FAIL");assert.equal(first.candidateQuality,null);assert.equal(first.summary.candidateQuality,null)}finally{await rm(root,{recursive:true,force:true})}});

test("CLI options reject run-id and unknown flags", () => {
  assert.deepEqual(parseEvaluationCliArgs(["--tier", "full", "--probe"]), { tier: "full", probe: true });
  assert.throws(() => parseEvaluationCliArgs(["--run-id", "caller"]), /unknown option: --run-id/);
  assert.throws(() => parseEvaluationCliArgs(["--legacy"]), /unknown option: --legacy/);
  assert.throws(() => parseEvaluationCliArgs(["--tier"]), /missing value/);
  assert.throws(() => parseEvaluationCliArgs(["--tier", "quick", "--tier", "full"]), /duplicate option/);
  assert.throws(() => parseEvaluationCliArgs(["--baseline", "refs/heads/main"]), /invalid baseline tag/);
  assert.throws(() => parseEvaluationCliArgs(["--tier", "invalid"]), /unknown tier/);
});

