test("dirty probe digest covers tracked and untracked content deterministically", async () => {
  const repo = await gitFixture(false);
  try {
    const clean = await dirtyProbeDigest(repo);
    assert.equal(clean, await dirtyProbeDigest(repo));
    await writeFile(join(repo, "b"), "two");
    await writeFile(join(repo, "a"), "one");
    const ordered = await dirtyProbeDigest(repo);
    await rm(join(repo, "a")); await rm(join(repo, "b"));
    await writeFile(join(repo, "a"), "one"); await writeFile(join(repo, "b"), "two");
    assert.equal(ordered, await dirtyProbeDigest(repo));
    await writeFile(join(repo, "a"), "changed");
    assert.notEqual(ordered, await dirtyProbeDigest(repo));
    await rm(join(repo, "a")); await rm(join(repo, "b"));
    const beforeTracked = await dirtyProbeDigest(repo);
    await writeFile(join(repo, "x"), "tracked change");
    assert.notEqual(beforeTracked, await dirtyProbeDigest(repo));
    await writeFile(join(repo, ".gitignore"), "ignored\n");
    const beforeIgnored = await dirtyProbeDigest(repo);
    await writeFile(join(repo, "ignored"), "one");
    assert.equal(beforeIgnored, await dirtyProbeDigest(repo));
    if (process.platform !== "win32") {
      await symlink("first", join(repo, "link"));
      const first = await dirtyProbeDigest(repo);
      await rm(join(repo, "link")); await symlink("second", join(repo, "link"));
      assert.notEqual(first, await dirtyProbeDigest(repo));
    }
  } finally { await rm(repo, { recursive: true, force: true }); }
});
