test("different runs in one rawDir do not contaminate resume or summary", async () => {
  const root = await mkdtemp(join(tmpdir(), "loom-eval-run-isolation-"));
  for (const arm of ["baseline", "candidate"]) for (const owner of new Set(CASES.flatMap(c => c.owners))) { await mkdir(join(root, arm, owner, ".."), { recursive: true }); await writeFile(join(root, arm, owner), arm); }
  try {
    const identity = { dir: join(root, "baseline"), ref: "v1", commit: "0123456789abcdef0123456789abcdef01234567", dirty: false, advisory: false }, candidate = { ...identity, dir: join(root, "candidate"), ref: "HEAD" }, env = isolatedChildEnv({ home: "/owned/home", agentDir: "/owned/agent", ompExecutable: "/opt/omp/bin/omp" });
    const judge = JSON.stringify({ A: { correctness: 4, autonomy: 4, actionability: 4, safety: 4, concision: 4 }, B: { correctness: 4, autonomy: 4, actionability: 4, safety: 4, concision: 4 }, blocker: false, notes: "ok" });
    let calls = 0, blocked = true;
    const passingOutput = () => receipt("Decision needed; stop with no materialization. Selective reference loading; unrelated reference not loaded. Inherited red is pre-existing. Escalate the material boundary. BLOCKED for incomplete evidence. Fresh confirmation required; no executable remote action. Fact lookup remains pending; independent decision continues. The dependent question is withheld until the prerequisite fact resolves. I will look up the fact myself. Which user-owned decision?");
    const fake = async (_command, args) => { calls++; if (blocked) throw Error("transport blocked"); return { stdout: args.includes("--model=gpt-5.6-sol") ? ompStream("gpt-5.6-sol", judge) : ompStream("claude-opus-5", passingOutput(String(args.at(-1)))) }; };
    const first = await executeEvaluation({ tier: "quick", baseline: identity, candidate, rawDir: join(root, "raw"), runId: "blocked-run", ompExecutable: "/opt/omp/bin/omp", exec: fake, env });
    blocked = false;
    const before = calls;
    const second = await executeEvaluation({ tier: "quick", baseline: identity, candidate, rawDir: join(root, "raw"), runId: "successful-run", ompExecutable: "/opt/omp/bin/omp", exec: fake, env });
    assert.equal(first.outcome, "BLOCKED"); assert.equal(second.outcome, "PASS", JSON.stringify(second)); assert.equal(second.summary.trials, 18); assert.notEqual(second.summary.candidateQuality, null);
    const after = calls; const resumed = await executeEvaluation({ tier: "quick", baseline: identity, candidate, rawDir: join(root, "raw"), runId: "successful-run", ompExecutable: "/opt/omp/bin/omp", exec: fake, env });
    const firstResumed = await executeEvaluation({ tier: "quick", baseline: identity, candidate, rawDir: join(root, "raw"), runId: "blocked-run", ompExecutable: "/opt/omp/bin/omp", exec: fake, env });
    assert.equal(calls, after); assert.deepEqual(resumed.summary, second.summary); assert.deepEqual(firstResumed.summary, first.summary); assert.ok(before < after);
  } finally { await rm(root, { recursive: true, force: true }); }
});

